"""Timing breakdown of one run log (jsonl from the Atira API): per phase, per agent, per kind of turn."""
import json
import re
import sys
from collections import defaultdict

rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8")]
stdout = [r for r in rows if r["stream"] == "stdout"]
t0 = stdout[0]["at"]
lines = []
for r in stdout:
    for text in r["text"].splitlines():
        lines.append(((r["at"] - t0) / 1000, text))

TURN = re.compile(r"^\[(?P<agent>[\w~:-]+) (?P<n>\d+) t\+(?P<t>\d+)s\] \(read (?P<read>[\d.]+)s, model (?P<model>[\d.]+)s, "
                  r"act (?P<act>[\d.]+)s\) (?P<rest>.*)$")


def kind_of(actions_text: str, thought: str) -> str:
    acts = re.findall(r'"do": "(\w+)"', actions_text)
    low = thought.lower() + " " + actions_text.lower()
    if not acts:
        return "no action"
    if "password" in low or "log in" in low or "login" in low or ('"fill", "id": 1' in actions_text and "u_" in actions_text):
        return "login"
    if "cookie" in low:
        return "cookie wall"
    if "slider" in low or "captcha" in low or "access check" in low or "robot" in low or "teilnahme" in low:
        return "access check / gate"
    if "done" in acts and len(acts) == 1:
        return "done (finish/idle)"
    if "enter_positions" in acts or "steps" in acts:
        return "form steps"
    if "ask_mail" in acts:
        return "ask mailbox (TAN)"
    if "finalize" in acts or "check_submission" in acts:
        return "sign / finalize"
    if "answer" in acts:
        return "close question"
    if "keep" in acts or "file_each" in acts:
        return "file evidence (keep)"
    if "collect" in acts or "fetch" in acts:
        return "collect / download"
    if "fill" in acts or "select" in acts or "set" in acts:
        return "fill / search / select"
    if "goto" in acts or "click" in acts or "back" in acts or "reload" in acts:
        return "navigate (click/goto/back)"
    return "other"


turns = []
for at, text in lines:
    m = TURN.match(text)
    if not m:
        continue
    rest = m["rest"]
    thought, _, after = rest.partition(" | ")
    actions_text, _, results = after.partition(" | ")
    turns.append({"at": at, "agent": m["agent"], "n": int(m["n"]), "read": float(m["read"]),
                  "model": float(m["model"]), "act": float(m["act"]), "thought": thought, "actions": actions_text,
                  "results": results, "kind": kind_of(actions_text, thought)})

marks = {}
for at, text in lines:
    for key, pat in (("context", r"^Context:"), ("investigation_end", r"^Investigation took"),
                     ("submission", r"^Submission:"), ("courier_start", r"^\[courier 00")):
        if key not in marks and re.search(pat, text):
            marks[key] = at
    m = re.match(r"^\[([\w~-]+)\] finished:", text)
    if m:
        marks[f"finished:{m[1]}"] = at
    m = re.match(r"^\[([\w~-]+) 00 t\+0s\] starting", text)
    if m:
        marks.setdefault(f"start:{m[1]}", at)

print("MARKS")
for k, v in sorted(marks.items(), key=lambda kv: kv[1]):
    print(f"  {v:7.1f}  {k}")

print("\nPER AGENT")
by_agent = defaultdict(list)
for t in turns:
    by_agent[t["agent"]].append(t)
for agent, ts in by_agent.items():
    first = marks.get(f"start:{agent}", ts[0]["at"])
    print(f"  {agent:16s} turns {len(ts):3d}  read {sum(t['read'] for t in ts):6.1f}  model {sum(t['model'] for t in ts):6.1f}  "
          f"act {sum(t['act'] for t in ts):6.1f}  first {first:6.1f}  last {ts[-1]['at']:6.1f}")

print("\nPER AGENT x KIND (turns, seconds read+model+act)")
for agent, ts in by_agent.items():
    agg = defaultdict(lambda: [0, 0.0])
    for t in ts:
        agg[t["kind"]][0] += 1
        agg[t["kind"]][1] += t["read"] + t["model"] + t["act"]
    print(f"  {agent}: " + "; ".join(f"{k} {n}x/{s:.0f}s" for k, (n, s) in sorted(agg.items(), key=lambda kv: -kv[1][1])))

print("\nSLOW TURNS (read+act > 8 s or model > 5 s)")
for t in turns:
    if t["read"] + t["act"] > 8 or t["model"] > 5:
        print(f"  {t['at']:7.1f} {t['agent']} #{t['n']} read {t['read']} model {t['model']} act {t['act']} | {t['thought'][:110]} | {t['results'][:140]}")

print("\nGAPS > 10 s in an agent's turns (waiting idle or blocked)")
for agent, ts in by_agent.items():
    prev = marks.get(f"start:{agent}")
    for t in ts:
        start_of_turn = t["at"] - (t["read"] + t["model"] + t["act"])
        if prev is not None and start_of_turn - prev > 10:
            print(f"  {agent}: {prev:6.1f} -> {start_of_turn:6.1f} ({start_of_turn - prev:5.1f} s) before turn #{t['n']}")
        prev = t["at"]

print("\nEXTRACTIONS (filed page -> facts arrive)")
for at, text in lines:
    m = re.match(r"^\[extract (\w+)\] (\S+)", text)
    if m:
        print(f"  {at:7.1f} {m[1]:16s} {m[2][:90]}")

print("\nALL TURNS")
for t in turns:
    print(f"  {t['at']:7.1f} {t['agent']:15s} #{t['n']:02d} r{t['read']:4.1f} m{t['model']:4.1f} a{t['act']:5.1f} [{t['kind']}] {t['thought'][:100]}")
